private getThinkingBorderColor(level: ThinkingLevel): (str: string) => string {
	// More thinking = more color (gray → dim colors → bright colors)
	switch (level) {
		case "off":
			return chalk.gray;
		case "minimal":
			return chalk.dim.blue;
		case "low":
			return chalk.blue;
		case "medium":
			return chalk.cyan;
		case "high":
			return chalk.magenta;
		default:
			return chalk.gray;
	}
}

